// CRYO CHAMBER / ASCENSION Questline bridge.
// The existing wellness_ascension_v1 store is the single source of truth. SERAPHIM does not create a second quest ledger.
const ascensionBaseQuests=[
 'Take a comfortable movement break',
 'Make time to rest and recharge',
 'Enjoy a nourishing meal or snack',
 'Check in with how you feel'
];
let cryoCanvasResizeObserver=null;
let cryoDrawFrame=0;
let cryoChartRange=7;
let cryoDailySource={};
let cryoStoreConnected=false;
let cryoChartModel=null;
