function handleRealtimeTool(name,args){try{if(name==='put_seraphim_into_standby'){executeStandby('realtime AI tool','STANDBY');return {ok:true,state:'STANDBY',message:'SERAPHIM entered standby.'}}if(name==='get_ascension_progress')return {ok:true,progress:ascensionGetProgressSummary()};if(name==='list_ascension_quests')return {ok:true,quests:ascensionGetProgressSummary().quests||[],progress:ascensionGetProgressSummary()};if(name==='add_ascension_quest'){const q=ascensionAddQuest(args.title);return {ok:true,added:q,progress:ascensionGetProgressSummary()}}if(name==='complete_ascension_quest'){const q=ascensionSetQuest(args.title,true);return {ok:true,result:q,progress:ascensionGetProgressSummary()}}if(name==='reopen_ascension_quest'){const q=ascensionSetQuest(args.title,false);return {ok:true,result:q,progress:ascensionGetProgressSummary()}}return {ok:false,message:'Unknown local action.'}}catch(e){return {ok:false,message:String(e.message||e)}}}

function normalizeVoiceCommand(text){return String(text||'').toLowerCase().normalize('NFKC').replace(/[’'.,!?;:]/g,' ').replace(/\s+/g,' ').trim()}
function isTakeFiveCommand(text){return /^(?:(?:hey )?seraphim )?take five$/.test(normalizeVoiceCommand(text))}
function isHibernateCommand(text){return /^(?:(?:hey )?seraphim )?(?:hibernate|enter hibernation|go into hibernation|go to sleep)$/.test(normalizeVoiceCommand(text))}
function isSleepCommand(text){return isTakeFiveCommand(text)||isHibernateCommand(text)}
function isWakeCommand(text){return /^(?:seraphim|hey seraphim|wake up|wake up seraphim|wake word|hey wake word|wake seraphim|seraphim wake up|seraphim awaken|awaken seraphim|activate seraphim)$/.test(normalizeVoiceCommand(text))}
