function appearsNonEnglish(text){const s=String(text||'').toLowerCase();const markers=/\b(ako|ikaw|siya|kami|tayo|kayo|sila|ang|ng|mga|ito|iyan|iyon|dito|diyan|doon|hindi|opo|oo|salamat|kumusta|kamusta|paano|bakit|saan|kailan|ano|sino|gusto|pwede|puwede|kailangan|naman|lang|kasi|pero|dahil|kung|para|natin|niyo|nyo|yung|iyon|ba|pa|na|po|wala|meron|mayroon|maganda|mahal|ingat|tara|sige|grabe|sobrang|ako'y|mo|ko|ka|si|kay|sa|at|ay|pero|kaya|talaga|ngayon|bukas|kahapon)\b/g;const hits=(s.match(markers)||[]).length;return hits>=2||/\b(ano ba|kumusta ka|anong oras|pwede ba|paano ito|salamat po)\b/.test(s)}
function enforceEnglishReply(text){const reply=String(text||'').trim();if(!reply)return 'I’m sorry, I could not prepare a reliable English response. Please try again.';return appearsNonEnglish(reply)?'I’m sorry, I could not verify that the response stayed in English. Please ask me again, and I will respond in English.':reply}
