function worldEscapeText(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function worldSafeUrl(raw){try{const u=new URL(raw);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}}
function worldSafeImageUrl(raw){const u=worldSafeUrl(raw);return u.startsWith('https://')?u:''}
function worldClassify(title){const t=(title||'').toLowerCase();if(/climate|weather|flood|wildfire|renewable|carbon|environment|storm|heatwave|energy transition/.test(t))return 'CLIMATE';if(/science|technology|artificial intelligence|\bai\b|space|robot|chip|cyber|research|quantum/.test(t))return 'SCIENCE / TECH';if(/economy|market|stock|inflation|trade|bank|business|finance|currency|oil price/.test(t))return 'ECONOMY';if(/diplomacy|foreign policy|summit|ceasefire|election|parliament|minister|president|sanction|security/.test(t))return 'DIPLOMACY';if(/health|medical|hospital|vaccine|education|school|society/.test(t))return 'HEALTH / SOCIETY';return 'WORLD'}
function worldGlyph(category){return category==='CLIMATE'?'◌':category==='SCIENCE / TECH'?'⌘':category==='ECONOMY'?'▥':category==='DIPLOMACY'?'⌖':category==='HEALTH / SOCIETY'?'✚':'◎'}
function worldCategoryArt(category){const theme=category==='CLIMATE'?['#164e42','#66dbad','#b7ffdb']:category==='SCIENCE / TECH'?['#151a54','#6c8eff','#9af5ff']:category==='ECONOMY'?['#4b2c13','#ffc66d','#fff0b0']:category==='DIPLOMACY'?['#401e49','#d78cff','#f8caff']:category==='HEALTH / SOCIETY'?['#103e50','#5eddd2','#c8fff8']:['#102b46','#3f9ab8','#b3f7ff'];const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="800" height="440" viewBox="0 0 800 440"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${theme[0]}"/><stop offset="1" stop-color="#020812"/></linearGradient><radialGradient id="r"><stop stop-color="${theme[2]}" stop-opacity=".8"/><stop offset="1" stop-color="${theme[1]}" stop-opacity=".02"/></radialGradient></defs><rect width="800" height="440" fill="url(#g)"/><circle cx="420" cy="210" r="185" fill="url(#r)"/><g stroke="${theme[1]}" stroke-opacity=".55" fill="none">${Array.from({length:8},(_,i)=>`<path d="M ${90+i*88} 18 V422"/>`).join('')}${Array.from({length:5},(_,i)=>`<path d="M40 ${65+i*68} H760"/>`).join('')}<circle cx="420" cy="210" r="142"/><ellipse cx="420" cy="210" rx="142" ry="48"/><ellipse cx="420" cy="210" rx="70" ry="142"/></g><g fill="${theme[2]}" fill-opacity=".9">${Array.from({length:38},(_,i)=>{const x=95+(i*137)%620,y=45+(i*79)%345;return `<circle cx="${x}" cy="${y}" r="${i%4===0?3:1.8}"/>`}).join('')}</g><text x="34" y="392" font-family="monospace" font-size="19" letter-spacing="5" fill="${theme[2]}" fill-opacity=".84">${category.replace(/&/g,'AND')}</text><text x="35" y="416" font-family="monospace" font-size="10" letter-spacing="3" fill="#c3dce8" fill-opacity=".6">ILLUSTRATIVE CATEGORY ART / NOT A NEWS PHOTOGRAPH</text></svg>`;return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)}
