function updateWorldStatus(label,kind=''){const el=$('worldStatus');el.textContent=label;el.classList.toggle('world-source-live',kind==='live');el.classList.toggle('world-source-error',kind==='error');el.classList.toggle('world-source-cached',kind==='cached');}
function worldLog(title,detail){worldEvents++;worldLogQueue.push({id:++worldLogId,title:String(title),detail:String(detail),time:new Date().toLocaleTimeString([], {hour12:false})});if(worldLogQueue.length>18)worldLogQueue.splice(0,worldLogQueue.length-18);$('worldLogCount').textContent=`${worldEvents.toString().padStart(2,'0')} EVENTS`;processWorldLogQueue()}
function processWorldLogQueue(){if(worldLogTyping||!worldLogQueue.length)return;worldLogTyping=true;const entry=worldLogQueue.shift(),list=$('worldNewsLog'),row=document.createElement('div');row.className='world-log-entry';const time=document.createElement('time');time.textContent=entry.time;const body=document.createElement('div'),head=document.createElement('strong'),detail=document.createElement('span'),cursor=document.createElement('span');detail.className='world-log-detail';cursor.className='typing-cursor';cursor.setAttribute('aria-hidden','true');body.append(head,document.createTextNode(' '),detail,cursor);row.append(time,body);list.prepend(row);while(list.children.length>10)list.lastElementChild.remove();const finish=()=>{cursor.remove();row.classList.add('is-complete');worldLogTyping=false;setTimeout(processWorldLogQueue,70)};typeText(head,entry.title,17,()=>typeText(detail,entry.detail,8,finish))}
function renderWorldStoryList(){const list=$('worldStoryList');list.replaceChildren();const indices=worldFilteredIndices();if(!indices.length){const empty=document.createElement('div');empty.className='world-search-empty';empty.textContent=worldStories.length?'NO REPORTS MATCH THIS SEARCH. Try another headline, publisher, place, or category.':'No reports are loaded yet. Fetch live headlines to query the news index.';list.append(empty)}indices.forEach(index=>{const story=worldStories[index],btn=document.createElement('button');btn.type='button';btn.className='world-story-row'+(index===worldSelectedIndex?' selected':'')+(story.isLive?'':' demo');btn.setAttribute('aria-pressed',String(index===worldSelectedIndex));btn.setAttribute('aria-label',`Open story ${index+1}: ${story.title}`);const img=document.createElement('img');img.src=story.image||worldCategoryArt(story.category);img.alt=story.imageUrl?'Publisher image for this article':'Illustrative category art, not a news photo';img.loading='lazy';img.onerror=()=>{img.onerror=null;img.src=worldCategoryArt(story.category)};const content=document.createElement('span');content.className='world-story-row-content';const tag=document.createElement('small');tag.className='story-row-tag';tag.textContent=story.isLive?(worldFeedState==='cached'?'CACHED ARTICLE':'LIVE ARTICLE'):'DEMO TILE';const title=document.createElement('strong');title.textContent=story.title;const meta=document.createElement('small');meta.textContent=`${story.domain} · ${story.place}`;content.append(tag,title,meta);btn.append(img,content);btn.addEventListener('click',()=>selectWorldStory(index,true));list.append(btn)});$('worldStoryCount').textContent=`${indices.length}/${worldStories.length} ITEMS · ${worldFeedState.toUpperCase()}`;renderWorldPins();}
