function stopLiveVoice(silent=false){realtimeClosing=true;try{if(realtimeChannel?.readyState==='open')realtimeChannel.send(JSON.stringify({type:'session.close'}))}catch{}try{realtimeChannel?.close()}catch{}realtimeChannel=null;if(realtimePeer){try{realtimePeer.ontrack=null;realtimePeer.close()}catch{}}realtimePeer=null;if(realtimeMicStream){realtimeMicStream.getTracks().forEach(t=>t.stop());realtimeMicStream=null}const audio=$('liveVoiceAudio');if(audio){audio.pause();audio.srcObject=null}setOrbSpeaking('realtimeVoice',false);liveAssistantLine=null;liveUserLine=null;realtimeClosing=false;if(!silent)resumeWakeWordAfterRealtime();syncLiveVoiceUi(prefs.liveVoiceUrl?'READY TO CONNECT':'NOT CONFIGURED',prefs.liveVoiceUrl?'Live session ended. Microphone tracks are stopped.':'No session active. Configure an endpoint to enable speech-to-speech.');if(!silent){addLiveVoiceLine('SYSTEM','Session ended. Microphone tracks stopped and local WebRTC resources released.');log('Realtime voice disconnected','Session closed and microphone resources released.');tone(430)}}
$('saveLiveVoiceEndpoint').addEventListener('click',()=>{const value=$('liveVoiceEndpointInput').value.trim();if(value&&!/^https:\/\//i.test(value)&&!/^http:\/\/(localhost|127\.0\.0\.1)(:\d+)?(\/|$)/i.test(value)){syncLiveVoiceUi('ERROR','Endpoint must use HTTPS, or localhost while developing.');return}prefs.liveVoiceUrl=value;try{localStorage.setItem(prefKey,JSON.stringify(prefs))}catch{toast('Endpoint could not be saved in local storage.');return}syncLiveVoiceUi(value?'READY TO CONNECT':'NOT CONFIGURED',value?'Endpoint saved locally. The API key stays in the server-side Worker secret.':'Endpoint cleared.');log(value?'Realtime voice endpoint saved':'Realtime voice endpoint cleared','Endpoint URL is stored only in this browser.');toast(value?'Realtime endpoint saved locally.':'Realtime endpoint removed.');tone(620)});
$('startLiveVoice').addEventListener('click',startLiveVoice);$('stopLiveVoice').addEventListener('click',()=>stopLiveVoice(false));$('clearLiveTranscript').addEventListener('click',()=>{$('liveVoiceTranscript').replaceChildren();addLiveVoiceLine('SYSTEM','Transcript cleared locally.');tone(430)});

function refreshVoiceInfo(){const out='speechSynthesis'in window;const SpeechRec=window.SpeechRecognition||window.webkitSpeechRecognition;$('speechSupport').textContent=out?'Available':'Unavailable';$('micSupport').textContent=SpeechRec?'Available':'Unavailable';$('voiceStatus').textContent=prefs.workerUrl?'WORKER CONFIGURED':'BROWSER FALLBACK';$('voiceExplain').textContent=prefs.workerUrl?'Worker URL is saved. Select Test configured voice to check whether the endpoint is reachable.':'No external voice Worker configured. Browser speech synthesis will be used when available.'}
let activeSpeakAudio=null,activeSpeakObjectUrl='',speechRequestToken=0;
async function speak(text){const token=++speechRequestToken;setOrbSpeaking('voice',false);if('speechSynthesis'in window)window.speechSynthesis.cancel();if(activeSpeakAudio){try{activeSpeakAudio.pause();activeSpeakAudio.currentTime=0}catch{}activeSpeakAudio=null}if(activeSpeakObjectUrl){URL.revokeObjectURL(activeSpeakObjectUrl);activeSpeakObjectUrl=''}const safeText=String(text||'').trim();if(!safeText)return;if(prefs.speechMode==='worker'&&prefs.workerUrl){try{const response=await fetch(prefs.workerUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:safeText,voiceId:prefs.voiceId||undefined})});if(!response.ok)throw new Error(`Worker returned HTTP ${response.status}`);const blob=await response.blob();if(token!==speechRequestToken)return;const url=URL.createObjectURL(blob),audio=new Audio(url);activeSpeakObjectUrl=url;activeSpeakAudio=audio;audio.onplay=()=>{if(token===speechRequestToken){setOrbSpeaking('voice',true);$('voiceStatus').textContent='SPEAKING · WORKER'}};audio.onended=()=>{if(token===speechRequestToken){setOrbSpeaking('voice',false);activeSpeakAudio=null;activeSpeakObjectUrl='';URL.revokeObjectURL(url);refreshVoiceInfo()}};audio.onerror=()=>{if(token===speechRequestToken){setOrbSpeaking('voice',false);activeSpeakAudio=null;activeSpeakObjectUrl='';URL.revokeObjectURL(url)}};await audio.play();if(token===speechRequestToken)$('voiceStatus').textContent='WORKER VOICE OK';return}catch(e){if(token!==speechRequestToken)return;setOrbSpeaking('voice',false);toast(`Worker voice failed (${e.message}); trying browser speech.`);log('Voice Worker failed','Falling back to browser speech synthesis.')}}if(token!==speechRequestToken)return;if(!('speechSynthesis'in window)){setOrbSpeaking('voice',false);toast('Browser speech synthesis is unavailable in this browser.');return}const u=new SpeechSynthesisUtterance(safeText);u.lang='en-US';const voices=window.speechSynthesis.getVoices?.()||[];const englishVoice=voices.find(v=>/^en(-|_)/i.test(v.lang)&&/natural|neural|enhanced|google|microsoft/i.test(v.name))||voices.find(v=>/^en(-|_)/i.test(v.lang));if(englishVoice)u.voice=englishVoice;u.rate=.96;u.pitch=.88;u.onstart=()=>{if(token===speechRequestToken){setOrbSpeaking('voice',true);$('voiceStatus').textContent='SPEAKING'}};u.onend=()=>{if(token===speechRequestToken){setOrbSpeaking('voice',false);refreshVoiceInfo()}};u.onerror=()=>{if(token===speechRequestToken){setOrbSpeaking('voice',false);refreshVoiceInfo()}};window.speechSynthesis.speak(u)}

function testVoice(){refreshVoiceInfo();speak('SERAPHIM. Voice output check complete. AI reasoning is not connected in this prototype.');log('Voice output test requested','Uses configured Worker if selected, otherwise browser speech.')}$('testSpeech').addEventListener('click',testVoice);$('testConfiguredVoice').addEventListener('click',()=>{saveSettings();testVoice()});
// Consent-based browser wake phrase. Recognition works only where SpeechRecognition is exposed,
// requires explicit microphone permission, and is not a device-level always-on listener.
const nexusEmbedded=window.parent!==window;let nexusHostOpen=!nexusEmbedded;let wakeRecognition=null,wakeWordEnabled=true,wakeWordSuspended=false,wakeRestartTimer=null,wakeLastActivationAt=0;
function paintWakeWordStatus(mode,hint=''){const status=$('wakeWordStatus'),btn=$('wakeWordBtn');if(!status||!btn)return;status.classList.toggle('is-listening',mode==='LISTENING');status.classList.toggle('is-error',mode==='UNAVAILABLE'||mode==='PERMISSION BLOCKED'||mode==='ERROR');$('wakeWordState').textContent='VOICE COMMANDS '+mode; if(hint)$('wakeWordHint').textContent=hint;btn.setAttribute('aria-pressed',String(wakeWordEnabled));btn.classList.toggle('listening',wakeWordEnabled&&!wakeWordSuspended);if(!wakeWordEnabled)btn.textContent='◉ ENABLE VOICE COMMANDS';else btn.textContent=wakeWordSuspended?'◉ VOICE COMMANDS PAUSED':'■ DISABLE VOICE COMMANDS';}
function clearWakeEngine(){clearTimeout(wakeRestartTimer);const old=wakeRecognition;wakeRecognition=null;if(old){old.onresult=null;old.onend=null;old.onerror=null;try{old.stop()}catch{}}}
function scheduleWakeRestart(delay=550){clearTimeout(wakeRestartTimer);if(!wakeWordEnabled||wakeWordSuspended||document.hidden||!nexusHostOpen||window.__seraphimClosing)return;wakeRestartTimer=setTimeout(startWakeRecognition,delay)}
function startWakeRecognition(){if(!wakeWordEnabled||wakeWordSuspended||document.hidden||!nexusHostOpen||window.__seraphimClosing||wakeRecognition)return;if(realtimePeer||recognition){paintWakeWordStatus('PAUSED FOR VOICE INPUT','Voice commands will resume after the active microphone session ends.');return}if(!window.isSecureContext&&location.hostname!=='localhost'&&location.hostname!=='127.0.0.1'){wakeWordEnabled=false;paintWakeWordStatus('ERROR','Automatic voice commands require HTTPS or localhost. Open SERAPHIM through GitHub Pages HTTPS or VS Code Live Server.');return}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){wakeWordEnabled=false;paintWakeWordStatus('UNAVAILABLE','This browser does not expose voice-command recognition. Try a supported browser on HTTPS or localhost; the chat microphone can still dictate where supported.');return}const rec=new SR();wakeRecognition=rec;rec.lang='en-US';rec.continuous=true;rec.interimResults=true;rec.maxAlternatives=3;rec.onstart=()=>paintWakeWordStatus('LISTENING','Voice commands active: say “SERAPHIM”, “wake up”, or “wake word” to wake; say “hibernate” or “take five” to sleep. Keep this HUD in the foreground; browser recognition may process audio remotely.');rec.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++){const result=e.results[i];if(!result.isFinal)continue;const transcript=String(result[0]?.transcript||'').trim();if(isSleepCommand(transcript)){const now=Date.now();if(now-wakeLastActivationAt<1200)continue;wakeLastActivationAt=now;if(isHibernateCommand(transcript))executeHibernate('voice command listener');else executeTakeFive('voice command listener');try{rec.stop()}catch{}break;}if(isWakeCommand(transcript)){const now=Date.now();if(now-wakeLastActivationAt<1200)continue;wakeLastActivationAt=now;if(!coreActive){setCore(true);log('Wake phrase detected',`Browser speech recognition matched “${normalizeVoiceCommand(transcript)}” and awakened SERAPHIM.`);toast('Wake phrase recognized. SERAPHIM awakened.');tone(980)}else{log('Wake phrase detected','SERAPHIM wake command was heard; the core is already active.');toast('SERAPHIM is already active.')}try{rec.stop()}catch{}break;}}};rec.onerror=e=>{const code=e.error||'unknown';if(['not-allowed','service-not-allowed','audio-capture'].includes(code)){wakeWordEnabled=false;clearWakeEngine();paintWakeWordStatus('PERMISSION BLOCKED',`Wake-word listening stopped (${code}). Check microphone permission and browser/site settings.`);toast('Voice commands stopped: '+code);return}paintWakeWordStatus('RECONNECTING',`Speech recognition reported ${code}; trying to reconnect while this page stays active.`)};rec.onend=()=>{if(wakeRecognition===rec)wakeRecognition=null;if(wakeWordEnabled&&!wakeWordSuspended&&!document.hidden&&nexusHostOpen){paintWakeWordStatus('RECONNECTING','Reopening browser recognition to continue listening for voice commands.');scheduleWakeRestart(650)}else if(!wakeWordEnabled)paintWakeWordStatus('OFF','Voice commands will auto-start on the next page load. Say “SERAPHIM”, “wake up”, or “wake word” to wake; say “hibernate” or “take five” to sleep. Browser recognition may process audio remotely.');};try{rec.start()}catch(e){wakeRecognition=null;if(/notallowed|permission/i.test(String(e?.name||e?.message))){wakeWordEnabled=false;paintWakeWordStatus('PERMISSION BLOCKED','Allow microphone access for this site, then enable voice commands again.')}else{paintWakeWordStatus('ERROR','Could not start browser recognition: '+String(e?.message||e));}toast('Could not start wake-word listener.');}}
function toggleWakeWord(){if(wakeWordEnabled){wakeWordEnabled=false;clearWakeEngine();paintWakeWordStatus('OFF','Voice commands are off. You can still awaken SERAPHIM with the on-screen button and dictate through the Cryo chat microphone.');log('Wake word disabled','Browser speech-recognition listener stopped.');toast('Wake word disabled.');return}if(realtimePeer){toast('End the realtime voice session before enabling the separate wake-word listener.');paintWakeWordStatus('PAUSED FOR VOICE LINK','Realtime voice already owns the microphone. Stop it before enabling wake word.');return}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){paintWakeWordStatus('UNAVAILABLE','This browser does not expose wake-word recognition. Try a supported browser on HTTPS or localhost; use the on-screen activation button otherwise.');toast('Wake-word recognition is unavailable in this browser.');return}if(!window.isSecureContext&&location.hostname!=='localhost'&&location.hostname!=='127.0.0.1'){paintWakeWordStatus('ERROR','Voice-command recognition generally requires HTTPS or localhost. Open this HUD through VS Code Live Server.');toast('Use HTTPS or localhost to enable wake word.');return}wakeWordEnabled=true;paintWakeWordStatus('STARTING','Requesting microphone permission for “SERAPHIM” and “take five” voice commands.');log('Wake word enabled','User explicitly enabled browser recognition for the SERAPHIM activation name.');startWakeRecognition();}
$('wakeWordBtn').addEventListener('click',toggleWakeWord);
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(wakeRecognition){const old=wakeRecognition;wakeRecognition=null;old.onend=null;try{old.stop()}catch{}}if(wakeWordEnabled&&!wakeWordSuspended)paintWakeWordStatus('PAUSED · TAB HIDDEN','Wake-word listening pauses when the HUD is in the background. Return to this tab to resume.')}else if(wakeWordEnabled&&!wakeWordSuspended){paintWakeWordStatus('RECONNECTING','Returning to foreground; restarting the wake-word listener.');scheduleWakeRestart(250)}});
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==window.parent||!event.data)return;if(event.data.type==='ASCENSION_SERAPHIM_OPEN'){nexusHostOpen=true;if(wakeWordEnabled){wakeWordSuspended=false;paintWakeWordStatus('STARTING','Nexus opened. Automatic voice commands are starting; allow microphone access if prompted.');scheduleWakeRestart(250)}}if(event.data.type==='ASCENSION_SERAPHIM_CLOSE'){nexusHostOpen=false;wakeWordSuspended=true;clearWakeEngine();if(recognition){const old=recognition;recognition=null;old.onend=null;try{old.stop()}catch{}}try{stopLiveVoice(true)}catch{}if('speechSynthesis'in window)window.speechSynthesis.cancel();setOrbSpeaking('voice',false);if(wakeWordEnabled)paintWakeWordStatus('PAUSED · NEXUS CLOSED','Voice commands pause while the Nexus overlay is closed and resume when reopened.');$('micBtn').textContent='🎙 Start dictation';$('chatMic').textContent='🎙'}});
function suspendWakeWordForRealtime(){if(!wakeWordEnabled)return;wakeWordSuspended=true;clearWakeEngine();paintWakeWordStatus('PAUSED FOR VOICE LINK','The realtime conversation is using the microphone. Wake-word detection pauses until the voice session ends.');}
function resumeWakeWordAfterRealtime(){if(!wakeWordEnabled||window.__seraphimClosing)return;wakeWordSuspended=false;paintWakeWordStatus('RECONNECTING','Realtime voice ended; restarting wake-word listening.');scheduleWakeRestart(500)}

function startRecognition(targetInput){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('Speech recognition is not supported in this browser. Try a supported browser or type your message.');return}if(recognition){try{recognition.stop()}catch{}recognition=null;return}if(wakeWordEnabled){wakeWordSuspended=true;clearWakeEngine();paintWakeWordStatus('PAUSED FOR DICTATION','Wake-word listening pauses while the chat microphone is in use. It resumes when dictation ends.')}recognition=new SR();recognition.lang='en-US';recognition.interimResults=false;recognition.maxAlternatives=1;recognition.onstart=()=>{toast('Listening… speak now.');$('micBtn').textContent='■ Stop dictation';$('chatMic').textContent='■ Stop'};recognition.onresult=e=>{const spoken=e.results?.[0]?.[0]?.transcript||'';if(spoken){if(isSleepCommand(spoken)){if(isHibernateCommand(spoken))executeHibernate('microphone dictation');else executeTakeFive('microphone dictation');return}if(isWakeCommand(spoken)){setCore(true);toast('Wake command accepted. SERAPHIM online.');return}targetInput.value=(targetInput.value?targetInput.value+' ':'')+spoken;targetInput.focus();toast('Dictation added. Review it before transmitting.')}};recognition.onerror=e=>toast(`Microphone unavailable: ${e.error||'permission or service error'}`);recognition.onend=()=>{recognition=null;$('micBtn').textContent='🎙 Start dictation';$('chatMic').textContent='🎙';if(wakeWordEnabled&&nexusHostOpen&&!document.hidden&&!window.__seraphimClosing){wakeWordSuspended=false;paintWakeWordStatus('RECONNECTING','Dictation ended. Restarting automatic voice commands.');scheduleWakeRestart(350)}};try{recognition.start()}catch(e){toast('Could not start microphone: '+e.message);recognition=null;if(wakeWordEnabled){wakeWordSuspended=false;scheduleWakeRestart(500)}}}
$('micBtn').addEventListener('click',()=>{navigate('command');startRecognition($('chatInput'))});$('chatMic').addEventListener('click',()=>startRecognition($('chatInput')));
$('refreshTelemetry').addEventListener('click',()=>{refreshTelemetry();toast('Browser telemetry refreshed.');log('Telemetry refreshed','Readings updated from available browser APIs.')});window.addEventListener('beforeunload',()=>{window.__seraphimClosing=true;wakeWordEnabled=false;clearWakeEngine();stopLiveVoice(true);if(recognition)try{recognition.stop()}catch{}if('speechSynthesis'in window)window.speechSynthesis.cancel();setOrbSpeaking('voice',false);if(audioContext&&audioContext.state!=='closed')audioContext.close().catch(()=>{})});
restoreChat();loadSettingsForm();initOrbAudioSpectrum();initOrbAudioSpectrum('worldOrbAudioSpectrum');initParticleOrb();initWorldSeraphimOrb();initCryo();applyPrefs();refreshTelemetry();refreshVoiceInfo();syncLiveVoiceUi();paintWakeWordStatus('STARTING','Voice commands are set to auto-start. If this browser has not granted microphone access, approve its prompt. Say “SERAPHIM”, “wake up”, or “wake word” to wake; say “hibernate” or “take five” to sleep.');setTimeout(()=>{if(wakeWordEnabled)startWakeRecognition()},450);animateVisualMetrics();log('Tactical interface ready',"Cryo Chamber linked to ASCENSION's existing Questline and progression history. Realtime voice remains optional until a secure endpoint is configured.");setTimeout(assembleHUD,70);
